template:
% 参数由系统自动注入：\def\radius{3} \def\nsides{6} \def\startangle{90} \def\showpolygon{1} \def\showcircumcircle{1} \def\showincircle{0} \def\showapothem{0} \def\showradii{0} \def\showcentralangle{0} \def\showcenter{1} \def\showlabels{1} \def\labelm{M}
% 视觉归一化：把外接圆直径缩放到 6cm，保证不同半径下图形视觉大小一致。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% 边数取整供 \foreach 与 \ifnum 使用（注入值可能带小数点）
\pgfmathtruncatemacro{\nsi}{\nsides}
\pgfmathsetmacro{\stepang}{360/\nsi}
% 边心距 = 外接圆半径 * cos(180/n)，同时也是内切圆半径
\pgfmathsetmacro{\apoth}{\radius*cos(180/\nsi)}
\pgfmathsetmacro{\angA}{\startangle}
\pgfmathsetmacro{\angB}{\startangle + \stepang}
\pgfmathsetmacro{\Ax}{\radius*cos(\angA)}
\pgfmathsetmacro{\Ay}{\radius*sin(\angA)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angB)}
\pgfmathsetmacro{\By}{\radius*sin(\angB)}
% 垂足 M 是边 AB 的中点，位于 A、B 位置角的角平分方向上
\pgfmathsetmacro{\Mang}{\startangle + \stepang/2}
\pgfmathsetmacro{\Mx}{\apoth*cos(\Mang)}
\pgfmathsetmacro{\My}{\apoth*sin(\Mang)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \ifnum\showcircumcircle>0
    \draw[thick] (0,0) circle [radius=\radius];
  \fi
  \ifnum\showincircle>0
    \draw[thick] (0,0) circle [radius=\apoth];
  \fi
  % 依次连接 n 个顶点；循环到 i=n 时正好回到起点，无需 cycle
  \ifnum\showpolygon>0
    \draw[thick] ({\Ax},{\Ay}) \foreach \i in {1,...,\nsi}{ -- ({\radius*cos(\startangle + \i*\stepang)},{\radius*sin(\startangle + \i*\stepang)}) };
  \fi
  \ifnum\showradii>0
    \draw[thick] (0,0) -- ({\Ax},{\Ay});
    \draw[thick] (0,0) -- ({\Bx},{\By});
  \fi
  % 中心角 ∠AOB = 360/n，沿逆时针从 A 扫到 B
  \ifnum\showcentralangle>0
    \pgfmathsetmacro{\carcr}{min(0.5/\figscale, \radius*0.32)}
    \draw[thick] ({\carcr*cos(\angA)},{\carcr*sin(\angA)}) arc[start angle=\angA, end angle=\angB, radius=\carcr];
  \fi
  % 边心距 OM 与垂足处的直角记号（OM⊥AB）
  \ifnum\showapothem>0
    \draw[thick] (0,0) -- ({\Mx},{\My});
    \pgfmathsetmacro{\halfside}{\radius*sin(180/\nsi)}
    \pgfmathsetmacro{\rmsz}{min(0.26/\figscale, \apoth*0.2, \halfside*0.4)}
    \pgfmathsetmacro{\rox}{-cos(\Mang)}
    \pgfmathsetmacro{\roy}{-sin(\Mang)}
    \pgfmathsetmacro{\rsx}{cos(\Mang+90)}
    \pgfmathsetmacro{\rsy}{sin(\Mang+90)}
    \draw[thick] ({\Mx + \rmsz*\rox},{\My + \rmsz*\roy}) -- ({\Mx + \rmsz*\rox + \rmsz*\rsx},{\My + \rmsz*\roy + \rmsz*\rsy}) -- ({\Mx + \rmsz*\rsx},{\My + \rmsz*\rsy});
    \fill ({\Mx},{\My}) circle [radius=\dotr pt];
    \node at ({(\apoth + 0.17*\radius)*cos(\Mang)},{(\apoth + 0.17*\radius)*sin(\Mang)}) {$\labelm$};
  \fi
  % 顶点字母：最多支持 12 边，按索引取字母，超出边数的跳过
  \ifnum\showlabels>0
    \foreach \i/\lb in {0/A,1/B,2/C,3/D,4/E,5/F,6/G,7/H,8/I,9/J,10/K,11/L}{
      \ifnum\i<\nsi\relax
        \pgfmathsetmacro{\vang}{\startangle + \i*\stepang}
        \fill ({\radius*cos(\vang)},{\radius*sin(\vang)}) circle [radius=\dotr pt];
        \node at ({1.14*\radius*cos(\vang)},{1.14*\radius*sin(\vang)}) {$\lb$};
      \fi
    }
  \fi
  \ifnum\showcenter>0
    \fill (0,0) circle [radius=\dotr pt];
    \node[below right] at (0,0) {$O$};
  \fi
\end{tikzpicture}
